import { readFile, writeFile, mkdir } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

// No build dependency: run from any directory with Node. Generated files are
// tracked so both the static Angular build and the mounted Keycloak theme work.
const root = fileURLToPath(new URL("../", import.meta.url));
const check = process.argv.includes("--check");
if (process.argv.slice(2).some(arg => arg !== "--check")) {
  throw new Error("Usage: node scripts/sync-branding.mjs [--check]");
}
const tokens = JSON.parse(await readFile(resolve(root, "design/branding.json"), "utf8"));
const css = "/* Generated by scripts/sync-branding.mjs. Edit design/branding.json. */\n:root {\n"
  + Object.entries(tokens).map(([key, value]) => `  --${key}: ${value};`).join("\n")
  + "\n}\n";
// Decorative trace with two endpoints; adjacent text supplies the accessible name.
const mark = `<path d="M4 10 32 6v7l-17 4v12"/>
  <circle cx="4" cy="10" r="3.25" fill="currentColor" stroke="none"/>
  <circle cx="15" cy="29" r="3.25" fill="currentColor" stroke="none"/>`;
const svg = `<!-- Generated by scripts/sync-branding.mjs. -->
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 36 36" fill="none" stroke="currentColor" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round">
  ${mark}
</svg>
`;
const favicon = `<!-- Generated by scripts/sync-branding.mjs. -->
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 48 48">
  <rect width="48" height="48" rx="12" fill="${tokens.bg}"/>
  <g transform="translate(6 6)" fill="none" color="${tokens['brand-logo']}" stroke="currentColor" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round">${mark}</g>
</svg>
`;
const logo = `<!-- Generated by scripts/sync-branding.mjs. -->
<svg xmlns="http://www.w3.org/2000/svg" width="430" height="110" viewBox="0 0 430 110" role="img" aria-labelledby="title">
  <title id="title">TraceLink — Follow service evidence</title>
  <defs><filter id="glow" x="-100%" y="-100%" width="300%" height="300%"><feDropShadow dx="0" dy="0" stdDeviation="2" flood-color="${tokens['brand-logo']}" flood-opacity="0.5"/><feDropShadow dx="0" dy="0" stdDeviation="6" flood-color="${tokens['brand-logo']}" flood-opacity="0.35"/></filter></defs>
  <rect width="430" height="110" fill="${tokens.bg}"/>
  <g transform="translate(38 14) scale(1.7)" fill="none" color="${tokens['brand-logo']}" stroke="currentColor" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round" filter="url(#glow)">${mark}</g>
  <text x="126" y="44" fill="${tokens.text}" font-family="${tokens['font-family']}" font-size="45" font-weight="750" letter-spacing="-1.6">TraceLink</text>
  <text x="126" y="82" fill="${tokens['text-muted']}" font-family="${tokens['font-family']}" font-size="20" letter-spacing="0.4">Follow service evidence</text>
</svg>
`;
const outputs = [
  ["apps/dashboard/src/branding/tokens.css", css],
  ["infra/keycloak/themes/telecom/login/resources/css/tokens.css", css],
  ["apps/dashboard/src/branding/mark.svg", svg],
  ["apps/dashboard/src/branding/favicon.svg", favicon],
  ["infra/keycloak/themes/telecom/login/resources/img/mark.svg", svg],
  ["docs/assets/tracelink-logo.svg", logo],
];
for (const [path, contents] of outputs) {
  const target = resolve(root, path);
  if (check) {
    const actual = await readFile(target, "utf8").catch(() => "");
    if (actual !== contents) {
      console.error(`Stale branding: ${path}. Run node scripts/sync-branding.mjs`);
      process.exitCode = 1;
    }
  } else {
    await mkdir(dirname(target), { recursive: true });
    await writeFile(target, contents);
  }
}
if (!process.exitCode) console.log(check ? "Shared branding is current." : "Shared branding generated.");
